// Signs a release build with the Play upload key, but only when the build asks
// for it with -PfandexPlay. Every other release build (the APKs sideloaded onto
// the phone) stays on the debug key, so an installed app can still be updated
// in place: Android refuses an update signed with a different key.
//
// The key and its passwords never enter the repo. They are read from Gradle
// properties, which live in ~/.gradle/gradle.properties on the machine that
// builds, or from environment variables of the same names. → docs/play-store.md
//
// mobile/android is generated by `expo prebuild`, so this edit has to be a
// config plugin: a hand edit to build.gradle is lost on the next prebuild.
const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "// withPlayUploadSigning";

const HELPER = `${MARKER}: read one upload-key setting, or stop the build saying which is missing.
def fandexUploadSetting(String name) {
    def value = project.findProperty(name) ?: System.getenv(name)
    if (!value) {
        throw new GradleException("A Play build (-PfandexPlay) needs \${name} in ~/.gradle/gradle.properties. See docs/play-store.md.")
    }
    return value
}

// A Play bundle carries every phone architecture: a build narrowed to one for
// a quick sideload must not reach the store.
if (project.hasProperty('fandexPlay')) {
    def archs = (project.findProperty('reactNativeArchitectures') ?: '').split(',')*.trim()
    if (!archs.contains('arm64-v8a') || !archs.contains('armeabi-v7a')) {
        throw new GradleException("A Play build (-PfandexPlay) needs armeabi-v7a and arm64-v8a, not only: \${archs.join(', ')}")
    }
}

android {`;

const UPLOAD_CONFIG = `        // Play upload key, only for a build run with -PfandexPlay (withPlayUploadSigning).
        if (project.hasProperty('fandexPlay')) {
            upload {
                storeFile file(fandexUploadSetting('FANDEX_UPLOAD_STORE_FILE'))
                storePassword fandexUploadSetting('FANDEX_UPLOAD_STORE_PASSWORD')
                keyAlias fandexUploadSetting('FANDEX_UPLOAD_KEY_ALIAS')
                keyPassword fandexUploadSetting('FANDEX_UPLOAD_KEY_PASSWORD')
            }
        }
    }
    buildTypes {`;

const RELEASE_SIGNING = `signingConfig project.hasProperty('fandexPlay') ? signingConfigs.upload : signingConfigs.debug`;

/** The edit itself, kept apart so a test can run it on the template's text. */
function applyPlayUploadSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  // The helper has to sit before the android block that calls it.
  const androidAt = gradle.search(/^android \{/m);
  if (androidAt < 0) throw new Error("withPlayUploadSigning: no `android {` block in app/build.gradle");
  let out = gradle.slice(0, androidAt) + HELPER + gradle.slice(androidAt + "android {".length);

  // The upload config goes at the end of signingConfigs, which the template
  // closes right before buildTypes opens.
  const closeSigning = /\r?\n {4}\}\r?\n {4}buildTypes \{/;
  if (!closeSigning.test(out)) throw new Error("withPlayUploadSigning: signingConfigs is not followed by buildTypes");
  out = out.replace(closeSigning, "\n" + UPLOAD_CONFIG);

  // Only the release build type changes its key.
  const release = /(release \{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (!release.test(out)) throw new Error("withPlayUploadSigning: the release build type has no debug signingConfig to replace");
  return out.replace(release, `$1${RELEASE_SIGNING}`);
}

function withPlayUploadSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== "groovy") throw new Error("withPlayUploadSigning: app/build.gradle is not Groovy");
    mod.modResults.contents = applyPlayUploadSigning(mod.modResults.contents);
    return mod;
  });
}

module.exports = withPlayUploadSigning;
module.exports.applyPlayUploadSigning = applyPlayUploadSigning;
